  window.addEventListener('hashchange', () => {
    const s = state();
    render();
    if (s.p !== last.p || s.view !== last.view) {
      window.scrollTo(0, 0);
      root.focus({ preventScroll: true });
    }
    last = s;
  });
  render();
})();
